CREATE TABLE payment_locks(order_id UUID PRIMARY KEY,cancelled BOOLEAN NOT NULL);
CREATE TABLE payments(id UUID PRIMARY KEY,order_id UUID NOT NULL UNIQUE,customer_id UUID NOT NULL,amount NUMERIC(18,2) NOT NULL CHECK(amount>=0),currency VARCHAR(3) NOT NULL,method VARCHAR(20) NOT NULL CHECK(method IN ('COD','ONLINE')),status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','SUCCESS','FAILED','CANCELLED','REFUNDED')),idempotency_key VARCHAR(128) NOT NULL UNIQUE,snapshot TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE payment_transactions(id UUID PRIMARY KEY,payment_id UUID NOT NULL REFERENCES payments(id),provider VARCHAR(30) NOT NULL,provider_transaction_id VARCHAR(255) NOT NULL,transaction_type VARCHAR(20) NOT NULL CHECK(transaction_type IN ('CHARGE','REFUND')),amount NUMERIC(18,2) NOT NULL CHECK(amount>=0),status VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(provider,provider_transaction_id));
CREATE INDEX idx_payments_customer ON payments(customer_id);
